<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\{Resource,ResourceFile,Download,FileView}; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\Support\Facades\Storage;
class DownloadController extends Controller {
 public function start(Request $request, Resource $resource, ResourceFile $file){abort_unless($file->resource_id===$resource->id,404);$ip=$request->ip()??'';$ua=(string)$request->userAgent();$hash=hash('sha256',$ip.'|'.$ua.'|'.config('app.key'));FileView::create(['resource_file_id'=>$file->id,'resource_id'=>$resource->id,'visitor_hash'=>$hash,'session_id'=>$request->session()->getId(),'user_id'=>optional($request->user())->id,'ip_address'=>$ip,'user_agent'=>$ua,'created_at'=>now()]);$download=Download::create(['resource_id'=>$resource->id,'resource_file_id'=>$file->id,'user_id'=>optional($request->user())->id,'visitor_hash'=>$hash,'ip_address'=>$ip,'user_agent'=>$ua,'quality'=>$file->quality,'download_token'=>(string)Str::uuid()]);$resource->increment('downloads_count');return response()->json(['token'=>$download->download_token,'url'=>route('api.download.stream',$download->download_token,absolute:false)]);}
 public function stream(string $token){$d=Download::where('download_token',$token)->with('file')->firstOrFail();abort_unless(Storage::disk('public')->exists($d->file->path),404);$name=$d->file->original_name;$extension=ltrim((string)$d->file->extension,'.');if($extension!==''&&!str_ends_with(strtolower($name),'.'.strtolower($extension))){$name.='.'. $extension;}return Storage::disk('public')->download($d->file->path,$name);}
}
